1: ///|
2: pub(all) struct Audit {
3:   schema_version : Int32
4:   plan : Plan
5:   inventory : Inventory
6:   left_multiplicity_groups : Int32
7:   right_multiplicity_groups : Int32
8:   issue_count : Int32
9:   safe : Bool
10:   witnesses : Array[Witness]
11:   witnesses_omitted : Int32
12: } derive(ToJson)
