23: ///|
24: fn evidence(
25:   out : Array[Witness],
26:   code : String,
27:   scope : String,
28:   key : Array[Cell],
29:   left_ids : Array[String],
30:   right_ids : Array[String],
31:   explanation : String,
32: ) -> Unit {
33:   if out.length() < 128 {
34:     out.push({ code, scope, key, left_ids, right_ids, explanation, })
35:   }
36: }
