38: ///|
39: /// Preflight every contract, while returning at most 128 explicit witnesses.
40: pub fn audit(left : Table, right : Table, p : Plan) -> Audit raise JoinError {
41:   let inv = inventory(left, right, p)
42:   let witnesses = []
43:   let mut issues = 0
44:   let mut left_bad = 0
45:   let mut right_bad = 0
46:   for group in inv.groups {
47:     if group.pairs == 0 {
48:       continue
49:     }
50:     if group.left_ids.length() > 1 &&
51:       ["one_to_one", "one_to_many"].contains(p.cardinality) {
52:       left_bad = left_bad + 1
53:       issues = issues + 1
54:       evidence(
55:         witnesses,
56:         "LEFT_MULTIPLICITY",
57:         "constructive",
58:         group.key.copy(),
59:         [group.left_ids[0], group.left_ids[1]],
60:         [group.right_ids[0]],
61:         "Two left facts match the same right fact; three rows reproduce the violation.",
62:       )
63:     }
64:     if group.right_ids.length() > 1 &&
65:       ["one_to_one", "many_to_one"].contains(p.cardinality) {
66:       right_bad = right_bad + 1
67:       issues = issues + 1
68:       evidence(
69:         witnesses,
70:         "RIGHT_MULTIPLICITY",
71:         "constructive",
72:         group.key.copy(),
73:         [group.left_ids[0]],
74:         [group.right_ids[0], group.right_ids[1]],
75:         "One left fact matches two right facts; three rows reproduce the violation.",
76:       )
77:     }
78:   }
79:   let li = indexes(left, p.keys, true)
80:   let ri = indexes(right, p.keys, false)
81:   let lr = row_index(left)
82:   let rr = row_index(right)
83:   if p.require_left {
84:     for id in inv.unmatched_left {
85:       issues = issues + 1
86:       let key = match key_of(lr[id], li, "equal") {
87:         Some(k) => k
88:         None => abort("null-safe projection must produce a key")
89:       }
90:       evidence(
91:         witnesses,
92:         "MISSING_RIGHT",
93:         "full_input_absence",
94:         key,
95:         [id],
96:         [],
97:         "This left fact has no eligible matching partner in the complete right table.",
98:       )
99:     }
100:   }
101:   if p.require_right {
102:     for id in inv.unmatched_right {
103:       issues = issues + 1
104:       let key = match key_of(rr[id], ri, "equal") {
105:         Some(k) => k
106:         None => abort("null-safe projection must produce a key")
107:       }
108:       evidence(
109:         witnesses,
110:         "MISSING_LEFT",
111:         "full_input_absence",
112:         key,
113:         [],
114:         [id],
115:         "This right fact has no eligible matching partner in the complete left table.",
116:       )
117:     }
118:   }
119:   if inv.output_rows > p.max_output.to_int64() {
120:     issues = issues + 1
121:     evidence(
122:       witnesses,
123:       "OUTPUT_BUDGET",
124:       "full_input",
125:       [],
126:       [],
127:       [],
128:       "Exact output cardinality exceeds the declared materialization budget.",
129:     )
130:   }
131:   {
132:     schema_version: 1,
133:     plan: { ..p, keys: p.keys.copy(), },
134:     inventory: inv,
135:     left_multiplicity_groups: left_bad,
136:     right_multiplicity_groups: right_bad,
137:     issue_count: issues,
138:     safe: issues == 0,
139:     witnesses_omitted: issues - witnesses.length(),
140:     witnesses,
141:   }
142: }
