144: ///|
145: fn selected(t : Table, ids : Array[String]) -> Array[Row]? {
146:   let lookup = row_index(t)
147:   let rows = []
148:   let seen : Map[String, Bool] = Map([])
149:   for id in ids {
150:     if seen.contains(id) {
151:       return None
152:     }
153:     seen[id] = true
154:     match lookup.get(id) {
155:       Some(row) => rows.push(row)
156:       None => return None
157:     }
158:   }
159:   Some(rows)
160: }
161: 
162: ///|
163: fn compatible(
164:   a : Row,
165:   b : Row,
166:   li : Array[Int32],
167:   ri : Array[Int32],
168:   nulls : String,
169: ) -> Bool {
170:   match (key_of(a, li, nulls), key_of(b, ri, nulls)) {
171:     (Some(x), Some(y)) => x == y
172:     _ => false
173:   }
174: }
