176: ///|
177: /// Recheck claimed evidence against the supplied complete source tables.
178: /// Explanation prose is not authenticated; only code/scope/keys/row IDs are facts.
179: pub fn verify_witness(
180:   left : Table,
181:   right : Table,
182:   p : Plan,
183:   w : Witness,
184: ) -> Bool raise JoinError {
185:   validate_table(left)
186:   validate_table(right)
187:   validate_plan(p)
188:   let li = indexes(left, p.keys, true)
189:   let ri = indexes(right, p.keys, false)
190:   let ls = match selected(left, w.left_ids) {
191:     Some(rows) => rows
192:     None => return false
193:   }
194:   let rs = match selected(right, w.right_ids) {
195:     Some(rows) => rows
196:     None => return false
197:   }
198:   match w.code {
199:     "LEFT_MULTIPLICITY" | "RIGHT_MULTIPLICITY" => {
200:       if w.scope != "constructive" {
201:         return false
202:       }
203:       if w.code == "LEFT_MULTIPLICITY" {
204:         if !["one_to_one", "one_to_many"].contains(p.cardinality) ||
205:           ls.length() != 2 ||
206:           rs.length() != 1 {
207:           return false
208:         }
209:       } else if !["one_to_one", "many_to_one"].contains(p.cardinality) ||
210:         ls.length() != 1 ||
211:         rs.length() != 2 {
212:         return false
213:       }
214:       for l in ls {
215:         if key_of(l, li, p.nulls) != Some(w.key) {
216:           return false
217:         }
218:         for r in rs {
219:           if !compatible(l, r, li, ri, p.nulls) {
220:             return false
221:           }
222:         }
223:       }
224:       true
225:     }
226:     "MISSING_RIGHT" => {
227:       if w.scope != "full_input_absence" ||
228:         !p.require_left ||
229:         ls.length() != 1 ||
230:         rs.length() != 0 {
231:         return false
232:       }
233:       if key_of(ls[0], li, "equal") != Some(w.key) {
234:         return false
235:       }
236:       !right.rows.any(r => compatible(ls[0], r, li, ri, p.nulls))
237:     }
238:     "MISSING_LEFT" => {
239:       if w.scope != "full_input_absence" ||
240:         !p.require_right ||
241:         rs.length() != 1 ||
242:         ls.length() != 0 {
243:         return false
244:       }
245:       if key_of(rs[0], ri, "equal") != Some(w.key) {
246:         return false
247:       }
248:       !left.rows.any(l => compatible(l, rs[0], li, ri, p.nulls))
249:     }
250:     "OUTPUT_BUDGET" =>
251:       w.scope == "full_input" &&
252:       w.key.length() == 0 &&
253:       ls.length() == 0 &&
254:       rs.length() == 0 &&
255:       inventory(left, right, p).output_rows > p.max_output.to_int64()
256:     _ => false
257:   }
258: }
259: 
260: ///|
261: /// Export a complete three-row reproducer; absence cannot use this mechanism.
262: pub fn counterexample(
263:   left : Table,
264:   right : Table,
265:   p : Plan,
266:   w : Witness,
267: ) -> (Table, Table) raise JoinError {
268:   if w.scope != "constructive" || !verify_witness(left, right, p, w) {
269:     invalid(
270:       "only valid constructive multiplicity witnesses have three-row reproducers",
271:     )
272:   }
273:   let ls = match selected(left, w.left_ids) {
274:     Some(rows) => rows
275:     None => abort("verified IDs disappeared")
276:   }
277:   let rs = match selected(right, w.right_ids) {
278:     Some(rows) => rows
279:     None => abort("verified IDs disappeared")
280:   }
281:   (
282:     {
283:       ..left,
284:       columns: left.columns.copy(),
285:       rows: ls.map(r => { ..r, values: r.values.copy(), }),
286:     },
287:     {
288:       ..right,
289:       columns: right.columns.copy(),
290:       rows: rs.map(r => { ..r, values: r.values.copy(), }),
291:     },
292:   )
293: }

1: ///|
2: /// Source-row identity pair. None denotes an outer-join null extension.
3: pub(all) struct Pair {
4:   left_id : String?
5:   right_id : String?
6: } derive(Eq, ToJson)
7: 
8: ///|
9: /// All preflight contracts must pass before any output pair array is built.
10: pub fn materialize(
11:   left : Table,
12:   right : Table,
13:   p : Plan,
14: ) -> Array[Pair] raise JoinError {
15:   let report = audit(left, right, p)
16:   if !report.safe {
17:     invalid(
18:       "materialization refused: cardinality, coverage or output budget contract failed",
19:     )
20:   }
21:   let pairs = []
22:   for group in report.inventory.groups {
23:     if group.pairs > 0 {
24:       for l in group.left_ids {
25:         for r in group.right_ids {
26:           pairs.push(Pair::{ left_id: Some(l), right_id: Some(r), })
27:         }
28:       }
29:     }
30:   }
31:   if p.kind == "left" || p.kind == "full" {
32:     for id in report.inventory.unmatched_left {
33:       pairs.push(Pair::{ left_id: Some(id), right_id: None, })
34:     }
35:   }
36:   if p.kind == "right" || p.kind == "full" {
37:     for id in report.inventory.unmatched_right {
38:       pairs.push(Pair::{ left_id: None, right_id: Some(id), })
39:     }
40:   }
41:   pairs.sort_by(fn(a, b) {
42:     match (a.left_id, b.left_id) {
43:       (Some(x), Some(y)) if x != y => x.compare(y)
44:       (None, Some(_)) => -1
45:       (Some(_), None) => 1
46:       _ =>
47:         match (a.right_id, b.right_id) {
48:           (Some(x), Some(y)) => x.compare(y)
49:           (None, Some(_)) => -1
50:           (Some(_), None) => 1
51:           _ => 0
52:         }
53:     }
54:   })
55:   pairs
56: }

1: ///|
2: /// Opaque mutable engine. Public queries and outcomes return detached arrays.
3: pub struct Engine {
4:   cfg : Config
5:   mut records : Map[String, Event]
6:   mut materialized : Array[Window]
7:   mut clock : Int32
8:   mut revision : Int32
9:   committed : Map[String, Command]
10:   journal : Array[Command]
11:   mut journal_units : Int32
12: }
13: 
14: ///|
15: pub fn Engine::new(cfg : Config) -> Engine raise TideError {
16:   validate_config(cfg)
17:   {
18:     cfg,
19:     records: Map([]),
20:     materialized: [],
21:     clock: 0,
22:     revision: 0,
23:     committed: Map([]),
24:     journal: [],
25:     journal_units: 0,
26:   }
27: }
28: 
29: ///|
30: fn copy_row(w : Window) -> Window {
31:   { ..w, members: w.members.copy(), }
32: }
33: 
34: ///|
35: fn copy_command(command : Command) -> Command {
36:   match command {
37:     Transact(id~, changes~) => Transact(id~, changes=changes.copy())
38:     Advance(..) => command
39:   }
40: }
41: 
42: ///|
43: /// Detached, sorted materialized view. Mutating its arrays cannot alter state.
44: pub fn Engine::rows(self : Engine) -> Array[Window] {
45:   self.materialized.map(copy_row)
46: }
47: 
48: ///|
49: pub fn Engine::events(self : Engine) -> Array[Event] {
50:   let result = []
51:   for _, e in self.records {
52:     result.push(e)
53:   }
54:   result.sort_by(fn(a, b) { a.id.compare(b.id) })
55:   result
56: }
57: 
58: ///|
59: pub fn Engine::watermark(self : Engine) -> Int32 {
60:   self.clock
61: }
62: 
63: ///|
64: pub fn Engine::version(self : Engine) -> Int32 {
65:   self.revision
66: }
67: 
68: ///|
69: fn command_id(c : Command) -> String {
70:   match c {
71:     Transact(id~, ..) | Advance(id~, ..) => id
72:   }
73: }
74: 
75: ///|
76: fn validate_command(c : Command) -> Unit raise TideError {
77:   validate_name(command_id(c))
78:   match c {
79:     Advance(to~, ..) =>
80:       if to < 0 || to > 2000000000 {
81:         fail("watermark must be in 0..2000000000")
82:       }
83:     Transact(changes~, ..) => {
84:       if changes.length() < 1 || changes.length() > 128 {
85:         fail("transaction requires 1..128 changes")
86:       }
87:       let seen : Map[String, Bool] = Map([])
88:       for m in changes {
89:         let id = match m {
90:           Put(e) => {
91:             validate_event(e)
92:             e.id
93:           }
94:           Remove(id) => {
95:             validate_name(id)
96:             id
97:           }
98:         }
99:         if seen.contains(id) {
100:           fail("one transaction cannot repeat an event ID")
101:         }
102:         seen[id] = true
103:       }
104:     }
105:   }
106: }
107: 
108: ///|
109: fn indexed(rows : Array[Window]) -> Map[(String, Int32, Int32), Window] {
110:   let result : Map[(String, Int32, Int32), Window] = Map([])
111:   for w in rows {
112:     result[(w.key, w.start, w.end)] = w
113:   }
114:   result
115: }
116: 
117: ///|
118: /// Stable delete/upsert order. Before images support guarded downstream replay.
119: fn difference(before : Array[Window], after : Array[Window]) -> Array[Delta] {
120:   let old = indexed(before)
121:   let fresh = indexed(after)
122:   let result = []
123:   for w in before {
124:     if !fresh.contains((w.key, w.start, w.end)) {
125:       result.push(Delta::{
126:         kind: "delete",
127:         before: Some(copy_row(w)),
128:         after: None,
129:       })
130:     }
131:   }
132:   for w in after {
133:     let previous = old.get((w.key, w.start, w.end))
134:     if previous != Some(w) {
135:       result.push(Delta::{
136:         kind: "upsert",
137:         before: previous.map(copy_row),
138:         after: Some(copy_row(w)),
139:       })
140:     }
141:   }
142:   result
143: }
144: 
145: ///|
146: fn Engine::candidate(
147:   self : Engine,
148:   c : Command,
149: ) -> (Map[String, Event], Array[Window], Int32) raise TideError {
150:   validate_command(c)
151:   if self.journal_units + c.to_json().stringify().length() > 2097152 {
152:     fail("serialized successful journal exceeds 2 Mi UTF-16 units")
153:   }
154:   if self.journal.length() >= self.cfg.max_operations {
155:     fail("successful command capacity exceeded")
156:   }
157:   match c {
158:     Advance(to~, ..) => {
159:       if to < self.clock {
160:         fail("watermark cannot move backwards")
161:       }
162:       let rows = self.materialized.map(w => {
163:         ..w,
164:         phase: phase(w.end, to, self.cfg.lateness),
165:       })
166:       (self.records, rows, to)
167:     }
168:     Transact(changes~, ..) => {
169:       let proposed : Map[String, Event] = Map([])
170:       for id, e in self.records {
171:         proposed[id] = e
172:       }
173:       let affected : Map[String, Bool] = Map([])
174:       for m in changes {
175:         match m {
176:           Put(e) => {
177:             if self.records.get(e.id) is Some(old) {
178:               affected[old.key] = true
179:             }
180:             proposed[e.id] = e
181:             affected[e.key] = true
182:           }
183:           Remove(id) => {
184:             let old = match self.records.get(id) {
185:               Some(e) => e
186:               None => fail("cannot remove an unknown event")
187:             }
188:             proposed.remove(id)
189:             affected[old.key] = true
190:           }
191:         }
192:       }
193:       if proposed.length() > self.cfg.max_events {
194:         fail("active event capacity exceeded")
195:       }
196:       let groups : Map[String, Array[Event]] = Map([])
197:       for _, e in proposed {
198:         if affected.contains(e.key) {
199:           match groups.get(e.key) {
200:             Some(bucket) => bucket.push(e)
201:             None => groups[e.key] = [e]
202:           }
203:         }
204:       }
205:       let next = []
206:       for w in self.materialized {
207:         if !affected.contains(w.key) {
208:           next.push(w)
209:         }
210:       }
211:       for key, bucket in groups {
212:         let rebuilt = match self.cfg.window {
213:           Session(gap~) => session_rows(self.cfg, key, bucket, self.clock, gap)
214:           _ => fixed_rows(self.cfg, key, bucket, self.clock)
215:         }
216:         for w in rebuilt {
217:           next.push(w)
218:         }
219:         if next.length() > 20000 {
220:           fail("window capacity exceeded")
221:         }
222:       }
223:       next.sort_by(row_order)
224:       let old = indexed(self.materialized)
225:       let fresh = indexed(next)
226:       for w in self.materialized {
227:         if w.phase == "final" {
228:           if fresh.get((w.key, w.start, w.end)) != Some(w) {
229:             fail("correction would change a finalized window")
230:           }
231:           // Equal sums do not permit rewriting the underlying finalized facts.
232:           for event_id in w.members {
233:             if proposed.get(event_id) != self.records.get(event_id) {
234:               fail("correction would change a finalized event")
235:             }
236:           }
237:         }
238:       }
239:       for w in next {
240:         if w.phase == "final" && old.get((w.key, w.start, w.end)) != Some(w) {
241:           fail("correction would create an already finalized window")
242:         }
243:       }
244:       (proposed, next, self.clock)
245:     }
246:   }
247: }
