249: ///|
250: /// All failures leave state, version, successful IDs and journal unchanged.
251: pub fn Engine::apply(self : Engine, command : Command) -> Outcome {
252:   let id = command_id(command)
253:   if self.committed.get(id) is Some(previous) {
254:     let same = previous == command
255:     return {
256:       id,
257:       status: if same {
258:         "duplicate"
259:       } else {
260:         "conflict"
261:       },
262:       version: self.revision,
263:       watermark: self.clock,
264:       deltas: [],
265:       message: if same {
266:         "already committed; no effects repeated"
267:       } else {
268:         "command ID already used with different content"
269:       },
270:     }
271:   }
272:   let (records, rows, watermark) = self.candidate(command) catch {
273:     TideError(message) =>
274:       return {
275:         id,
276:         status: "rejected",
277:         version: self.revision,
278:         watermark: self.clock,
279:         deltas: [],
280:         message,
281:       }
282:   }
283:   let deltas = difference(self.materialized, rows)
284:   self.records = records
285:   self.materialized = rows
286:   self.clock = watermark
287:   self.revision = self.revision + 1
288:   let detached = copy_command(command)
289:   self.committed[id] = detached
290:   self.journal.push(detached)
291:   self.journal_units = self.journal_units +
292:     detached.to_json().stringify().length()
293:   {
294:     id,
295:     status: "accepted",
296:     version: self.revision,
297:     watermark,
298:     deltas,
299:     message: "committed atomically",
300:   }
301: }

1: ///|
2: /// Mathematical floor division. MoonBit division truncates toward zero.
3: fn floor_div(a : Int64, b : Int64) -> Int64 {
4:   let q = a / b
5:   if a < 0 && a % b != 0 {
6:     q - 1
7:   } else {
8:     q
9:   }
10: }
11: 
12: ///|
13: /// Return start/end pairs in ascending order, including negative starts.
14: pub fn assign_fixed(
15:   spec : WindowSpec,
16:   at : Int32,
17: ) -> Array[(Int32, Int32)] raise TideError {
18:   if at < 0 || at > 1000000000 {
19:     fail("invalid event time")
20:   }
21:   let (size, slide, offset) = match spec {
22:     Tumbling(size~, offset~) => (size, size, offset)
23:     Sliding(size~, slide~, offset~) => (size, slide, offset)
24:     Session(..) => fail("assign_fixed requires a fixed window")
25:   }
26:   validate_fixed(size, slide, offset)
27:   let t = at.to_int64()
28:   let width = size.to_int64()
29:   let step = slide.to_int64()
30:   let shift = offset.to_int64()
31:   let last = floor_div(t - shift, step)
32:   let first = floor_div(t - shift - width, step) + 1
33:   let result = []
34:   for index = first; index <= last; index = index + 1 {
35:     let start = index * step + shift
36:     let end = start + width
37:     // Validated bounds imply -1e9 <= start and end <= 2e9.
38:     result.push((start.to_int(), end.to_int()))
39:   }
40:   result
41: }
42: 
43: ///|
44: fn phase(end : Int32, watermark : Int32, lateness : Int32) -> String {
45:   if watermark.to_int64() >= end.to_int64() + lateness.to_int64() {
46:     "final"
47:   } else if watermark >= end {
48:     "closing"
49:   } else {
50:     "open"
51:   }
52: }
53: 
54: ///|
55: fn row_from_events(
56:   key : String,
57:   start : Int32,
58:   end : Int32,
59:   events : Array[Event],
60:   watermark : Int32,
61:   lateness : Int32,
62: ) -> Window {
63:   let mut sum : Int64 = 0
64:   let mut low = events[0].value
65:   let mut high = events[0].value
66:   let members = []
67:   for e in events {
68:     sum = sum + e.value.to_int64()
69:     low = if e.value < low { e.value } else { low }
70:     high = if e.value > high { e.value } else { high }
71:     members.push(e.id)
72:   }
73:   members.sort()
74:   {
75:     key,
76:     start,
77:     end,
78:     count: events.length(),
79:     sum,
80:     min: low,
81:     max: high,
82:     members,
83:     phase: phase(end, watermark, lateness),
84:   }
85: }
