87: ///|
88: fn row_order(a : Window, b : Window) -> Int32 {
89:   if a.key != b.key {
90:     a.key.compare(b.key)
91:   } else if a.start != b.start {
92:     a.start.compare(b.start)
93:   } else {
94:     a.end.compare(b.end)
95:   }
96: }
