98: ///|
99: /// Aggregate one already isolated key, without encoding tuple keys as text.
100: fn fixed_rows(
101:   c : Config,
102:   key : String,
103:   events : Array[Event],
104:   watermark : Int32,
105: ) -> Array[Window] raise TideError {
106:   let buckets : Map[Int32, Array[Event]] = Map([])
107:   let ends : Map[Int32, Int32] = Map([])
108:   for e in events {
109:     for pair in assign_fixed(c.window, e.at) {
110:       let (start, end) = pair
111:       match buckets.get(start) {
112:         Some(bucket) => bucket.push(e)
113:         None => {
114:           buckets[start] = [e]
115:           ends[start] = end
116:         }
117:       }
118:     }
119:   }
120:   let rows = []
121:   for start, bucket in buckets {
122:     rows.push(
123:       row_from_events(key, start, ends[start], bucket, watermark, c.lateness),
124:     )
125:   }
126:   rows.sort_by(row_order)
127:   rows
128: }
