130: ///|
131: /// Batch aggregation API. Validates the same bounds used by the state machine.
132: pub fn aggregate(
133:   c : Config,
134:   events : Array[Event],
135:   watermark~ : Int32 = 0,
136: ) -> Array[Window] raise TideError {
137:   validate_config(c)
138:   if events.length() > c.max_events {
139:     fail("active event capacity exceeded")
140:   }
141:   if watermark < 0 || watermark > 2000000000 {
142:     fail("watermark out of range")
143:   }
144:   let grouped : Map[String, Array[Event]] = Map([])
145:   let ids : Map[String, Bool] = Map([])
146:   for e in events {
147:     validate_event(e)
148:     if ids.contains(e.id) {
149:       fail("duplicate event ID")
150:     }
151:     ids[e.id] = true
152:     match grouped.get(e.key) {
153:       Some(bucket) => bucket.push(e)
154:       None => grouped[e.key] = [e]
155:     }
156:   }
157:   let result = []
158:   for key, bucket in grouped {
159:     let rows = match c.window {
160:       Session(gap~) => session_rows(c, key, bucket, watermark, gap)
161:       _ => fixed_rows(c, key, bucket, watermark)
162:     }
163:     for row in rows {
164:       result.push(row)
165:     }
166:     if result.length() > 20000 {
167:       fail("window capacity exceeded")
168:     }
169:   }
170:   result.sort_by(row_order)
171:   result
172: }
173: 
174: ///|
175: /// Rebuild connected components after corrections, including deletion splits.
176: fn session_rows(
177:   c : Config,
178:   key : String,
179:   events : Array[Event],
180:   watermark : Int32,
181:   gap : Int32,
182: ) -> Array[Window] {
183:   let sorted = events.copy()
184:   sorted.sort_by(fn(a, b) {
185:     if a.at == b.at {
186:       a.id.compare(b.id)
187:     } else {
188:       a.at.compare(b.at)
189:     }
190:   })
191:   let rows = []
192:   let mut begin = 0
193:   for i in 1..<=sorted.length() {
194:     if i == sorted.length() || sorted[i].at - sorted[i - 1].at >= gap {
195:       let component = []
196:       for j in begin..<i {
197:         component.push(sorted[j])
198:       }
199:       rows.push(
200:         row_from_events(
201:           key,
202:           sorted[begin].at,
203:           sorted[i - 1].at + gap,
204:           component,
205:           watermark,
206:           c.lateness,
207:         ),
208:       )
209:       begin = i
210:     }
211:   }
212:   rows
213: }

1: ///|
2: /// A downstream materialized view that rejects gaps and stale before-images.
3: pub struct View {
4:   mut materialized : Array[Window]
5:   mut revision : Int32
6:   mut clock : Int32
7:   mut last_delivery : String
8: }
9: 
10: ///|
11: pub fn View::new() -> View {
12:   { materialized: [], revision: 0, clock: 0, last_delivery: "", }
13: }
14: 
15: ///|
16: pub fn View::rows(self : View) -> Array[Window] {
17:   self.materialized.map(copy_row)
18: }
19: 
20: ///|
21: pub fn View::version(self : View) -> Int32 {
22:   self.revision
23: }
24: 
25: ///|
26: /// Validates transport consistency; authenticity is the host's responsibility.
27: pub fn View::apply(self : View, outcome : Outcome) -> Unit raise TideError {
28:   if outcome.status != "accepted" {
29:     if !["duplicate", "conflict", "rejected"].contains(outcome.status) ||
30:       outcome.version != self.revision ||
31:       outcome.watermark != self.clock ||
32:       outcome.deltas.length() != 0 {
33:       fail("noncommitting outcome is inconsistent with local view")
34:     }
35:     return
36:   }
37:   let delivery = outcome.to_json().stringify()
38:   if outcome.version == self.revision && delivery == self.last_delivery {
39:     return
40:   }
41:   if outcome.version != self.revision + 1 {
42:     fail("view version gap or conflicting delivery")
43:   }
44:   if outcome.watermark < self.clock {
45:     fail("view watermark cannot move backwards")
46:   }
47:   let proposed = indexed(self.materialized)
48:   let touched : Map[(String, Int32, Int32), Bool] = Map([])
49:   for delta in outcome.deltas {
50:     let w = match (delta.kind, delta.before, delta.after) {
51:       ("delete", Some(before), None) => before
52:       ("upsert", _, Some(after)) => after
53:       _ => fail("invalid delta shape")
54:     }
55:     let key = (w.key, w.start, w.end)
56:     if touched.contains(key) {
57:       fail("duplicate row identity in one delivery")
58:     }
59:     touched[key] = true
60:     if delta.before is Some(before) {
61:       if (before.key, before.start, before.end) != key {
62:         fail("upsert changed identity")
63:       }
64:     }
65:     if proposed.get(key) != delta.before {
66:       fail("stale or missing before image")
67:     }
68:     match delta.after {
69:       Some(after) => proposed[key] = copy_row(after)
70:       None => proposed.remove(key)
71:     }
72:   }
73:   if proposed.length() > 20000 {
74:     fail("view capacity exceeded")
75:   }
76:   let rows = []
77:   for _, w in proposed {
78:     rows.push(w)
79:   }
80:   rows.sort_by(row_order)
81:   self.materialized = rows
82:   self.revision = outcome.version
83:   self.clock = outcome.watermark
84:   self.last_delivery = delivery
85: }

