2: /// Reject duplicate decoded keys before any domain decoding.
3: fn strict_json(source : String) -> Json raise TideError {
4:   if source.length() > 8388608 {
5:     fail("JSON exceeds 8 Mi UTF-16 units")
6:   }
7:   @json.parse(
8:     source,
9:     max_nesting_depth=24,
10:     reject_duplicate_keys=true,
11:     preserve_number_repr=true,
12:   ) catch {
13:     _ => fail("invalid JSON, duplicate key, or nesting exceeds 24")
14:   }
15: }
