4: // Exact numeric semantics for JSON Schema numeric keywords (2020-12 §6.2).
5: //
6: // Every predicate here is exact. There is no epsilon: `0.3` IS a multiple of
7: // `0.1`, and `1.0000000001` is NOT a multiple of `1`, however convenient the
8: // opposite would be for floating-point arithmetic. This layer deliberately
9: // avoids tolerance checks and rounded quotients.
10: 
11: ///|
12: /// A number taken from a JSON tree, kept exactly.
13: ///
14: /// `Repr` numbers carry the literal as written (`"0.3"`, `"1e10"`); `Double`
15: /// numbers were constructed in code and only the IEEE value remains. The
16: /// representation stays private: literal validation is exact, while `Double`
17: /// validation uses the finite double's shortest decimal rendering. Original
18: /// digits discarded by another parser cannot be recovered.
19: pub enum ExactNumber {
20:   Repr(coeff~ : @bigint.BigInt, scale~ : Int32)
21:   Double(Double)
22: }
23: 
24: ///|
25: /// A Json number node read as exactly as the source allows: parsed trees
26: /// carry only the double (`@json.parse` does not keep literal text on this
27: /// toolchain — verified by probe), constructed trees may carry a repr.
28: pub fn ExactNumber::of_json(v : Json) -> ExactNumber? {
29:   match v {
30:     Number(d, repr~) =>
31:       match repr {
32:         Some(text) => {
33:           let exact = ExactNumber::from_literal(text)
34:           guard exact is Some(_) else { return None }
35:           let parsed = literal_double(text)
36:           match parsed {
37:             Some(binary) => if binary != d || d.is_nan() { None } else { exact }
38:             None => None
39:           }
40:         }
41:         None => if d.is_inf() || d.is_nan() { None } else { Some(Double(d)) }
42:       }
43:     _ => None
44:   }
45: }

220: fn ExactNumber::parts(
221:   self : ExactNumber,
222: ) -> (@bigint.BigInt, Int32) raise NumericError {
223:   match self {
224:     Repr(coeff~, scale~) => {
225:       if scale < -100000 || scale > 100000 {
226:         raise InvalidNumber
227:       }
228:       (coeff, scale)
229:     }
230:     Double(value) => {
231:       if value.is_inf() || value.is_nan() {
232:         raise InvalidNumber
233:       }
234:       match ExactNumber::from_literal(value.to_string()) {
235:         Some(Repr(coeff~, scale~)) => (coeff, scale)
236:         _ => raise InvalidNumber
237:       }
238:     }
239:   }
240: }
