242: ///|
243: fn decimal_power(exponent : Int32) -> @bigint.BigInt {
244:   @bigint.BigInt::from_int(10).pow(@bigint.BigInt::from_int(exponent))
245: }
246: 
247: ///|
248: fn aligned(
249:   left : ExactNumber,
250:   right : ExactNumber,
251: ) -> (@bigint.BigInt, @bigint.BigInt) raise NumericError {
252:   let (a, sa) = left.parts()
253:   let (b, sb) = right.parts()
254:   if sa < sb {
255:     (a * decimal_power(sb - sa), b)
256:   } else if sa > sb {
257:     (a, b * decimal_power(sa - sb))
258:   } else {
259:     (a, b)
260:   }
261: }
262: 
263: ///|
264: /// Decimal integer predicate; no rounding or floating-point tolerance.
265: pub fn ExactNumber::is_integer(self : ExactNumber) -> Bool raise NumericError {
266:   let (coefficient, scale) = self.parts()
267:   scale <= 0 || coefficient.mod(decimal_power(scale)).is_zero()
268: }
269: 
270: ///|
271: /// Mathematical equality, including differently spelled decimal numbers.
272: pub fn ExactNumber::equal(
273:   self : ExactNumber,
274:   other : ExactNumber,
275: ) -> Bool raise NumericError {
276:   let (a, b) = aligned(self, other)
277:   a == b
278: }
279: 
280: ///|
281: pub fn ExactNumber::compare(
282:   self : ExactNumber,
283:   other : ExactNumber,
284: ) -> Int32 raise NumericError {
285:   let (a, b) = aligned(self, other)
286:   if a < b {
287:     -1
288:   } else if a > b {
289:     1
290:   } else {
291:     0
292:   }
293: }
294: 
295: ///|
296: /// Exact divisibility of aligned integer coefficients, never rounded division.
297: pub fn ExactNumber::multiple_of(
298:   self : ExactNumber,
299:   divisor : ExactNumber,
300: ) -> Bool raise NumericError {
301:   if divisor.sign() <= 0 {
302:     return false
303:   }
304:   let (a, b) = aligned(self, divisor)
305:   a.mod(b).is_zero()
306: }
307: 
308: ///|
309: pub fn ExactNumber::sign(self : ExactNumber) -> Int32 raise NumericError {
310:   let (coefficient, _) = self.parts()
311:   let zero = @bigint.BigInt::from_int(0)
312:   if coefficient < zero {
313:     -1
314:   } else if coefficient > zero {
315:     1
316:   } else {
317:     0
318:   }
